CREATE TABLE IF NOT EXISTS "prompt_suites" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "description" TEXT, "category" TEXT, "source_url" TEXT, "tags" TEXT, "sort_order" INTEGER NOT NULL DEFAULT 0, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), "updated_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'));
CREATE TABLE IF NOT EXISTS "prompt_cases" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "suite_id" INTEGER NOT NULL, "title" TEXT NOT NULL, "prompt" TEXT NOT NULL, "expected_answer" TEXT, "answer_notes" TEXT, "judge_mode" TEXT NOT NULL DEFAULT 'manual', "tags" TEXT, "sort_order" INTEGER NOT NULL DEFAULT 0, "enabled" BOOLEAN NOT NULL DEFAULT true, "created_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), "updated_at" TEXT DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), FOREIGN KEY ("suite_id") REFERENCES "prompt_suites"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "prompt_cases_suite_title_unique" ON "prompt_cases" ("suite_id", "title");
CREATE UNIQUE INDEX "prompt_suites_slug_unique" ON "prompt_suites" ("slug");
CREATE INDEX "prompt_cases_enabled_idx" ON "prompt_cases" ("enabled");
CREATE INDEX "prompt_cases_suite_id_idx" ON "prompt_cases" ("suite_id");
CREATE INDEX "prompt_suites_category_idx" ON "prompt_suites" ("category");
